import { Component, computed, inject, resource, signal } from '@angular/core';
import { DatePipe } from '@angular/common';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { Solicitud } from '../../../shared/models/solicitud.model';
import { semaforoColorClass } from '../../../shared/models/solicitud-status.util';
import { SolicitudService } from '../../../shared/services/solicitud.service';
import { ObservacionesService } from '../../../shared/services/observaciones.service';
import { AuthService } from '../../../services/auth.service';
import { NavigationHistoryService } from '../../../services/navigation-history.service';
import { HistorialTimelineComponent } from '../../../shared/components/historial-timeline/historial-timeline.component';
import { PdfViewerComponent } from '../../../shared/components/pdf-viewer/pdf-viewer.component';
import { ResolucionService } from '../../../shared/services/resolucion.service';
import { ChatInversorComponent } from '../seguimiento-municipal/chat-inversor/chat-inversor.component';
import { BitacoraNotasComponent } from '../seguimiento-municipal/bitacora-notas/bitacora-notas.component';

@Component({
  selector: 'app-ejecutivos-detalle-solicitud',
  imports: [RouterLink, HistorialTimelineComponent, PdfViewerComponent, DatePipe, ChatInversorComponent, BitacoraNotasComponent],
  templateUrl: './detalle-solicitud.component.html',
  styleUrl: './detalle-solicitud.component.scss',
})
export class DetalleSolicitudComponent {
  readonly semaforoColorClass = semaforoColorClass;

  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private solicitudService = inject(SolicitudService);
  private obsService = inject(ObservacionesService);
  private auth = inject(AuthService);
  private resolucionService = inject(ResolucionService);
  private navHistory = inject(NavigationHistoryService);

  folio = this.route.snapshot.paramMap.get('id') ?? '—';

  readonly origen = signal<'ejecutivo' | 'inversor'>(
    (this.route.snapshot.data['origen'] as 'ejecutivo' | 'inversor') ?? 'ejecutivo',
  );

  readonly solicitudResource = resource({
    params: () => ({ folio: this.folio }),
    loader: ({ params }) => firstValueFrom(this.solicitudService.getByFolio(params.folio)),
  });

  readonly solicitud = computed<Solicitud | null>(() => {
    return (this.solicitudResource.status() as string) === 'resolved' ? (this.solicitudResource.value() ?? null) : null;
  });
  readonly isLoading = computed(() => this.solicitudResource.isLoading());
  readonly hasError = computed(() => {
    return this.solicitudResource.hasValue() && !this.solicitudResource.value() || !!this.solicitudResource.error();
  });

  readonly correcciones = computed(() =>
    this.obsService
      .observacionesDe(this.folio)
      .filter((o) => o.status === 'pendiente')
      .map((o) => ({ id: o.id, descripcion: o.texto, fechaLimite: '—' })),
  );

  readonly esIncompleta = computed(() => this.solicitud()?.status === 'Incompleta');

  readonly mostrarCorrecciones = computed(
    () => this.esIncompleta() && this.correcciones().length > 0,
  );

  get regresarRoute(): string {
    return this.navHistory.getBackRoute(this.origen(), 'bandeja/recibidas', this.getQueryParams()['from']);
  }

  goBack(): void {
    this.router.navigateByUrl(this.regresarRoute);
  }

  constructor() {
    if (this.origen() === 'inversor') {
      this.obsService.cargar(this.folio);
    }
  }

  readonly canAccessResolucion = computed(() => {
    const user = this.auth.currentUser();
    const sol = this.solicitud();
    if (!user || !sol) return false;
    const isInternal = user.role === 'ejecutivo' || user.role === 'admin';
    return isInternal && sol.status === 'En Dictaminación';
  });

  readonly selectedDocId = signal<number | null>(null);
  readonly mostrarVisor = signal(false);
  readonly mostrarChat = signal(false);
  readonly mostrarBitacora = signal(false);

  seleccionarDocumento(id: number): void {
    this.selectedDocId.set(id);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    this.mostrarVisor.set(false);
    this.selectedDocId.set(null);
  }

  toggleChat(): void {
    this.mostrarChat.update(v => !v);
  }

  toggleBitacora(): void {
    this.mostrarBitacora.update(v => !v);
  }

  readonly canDesignarComite = computed(() => {
    const user = this.auth.currentUser();
    const sol = this.solicitud();
    if (!user || !sol) return false;
    const isInternal = user.role === 'ejecutivo' || user.role === 'admin';
    return isInternal && ['Enviada', 'Incompleta', 'Subsanada', 'No Presentada'].includes(sol.status);
  });

  getQueryParams(): Record<string, string> {
    const fromParam = this.route.snapshot.queryParamMap.get('from');
    return fromParam ? { from: fromParam } : {};
  }

  consultarResolucion(): void {
    if (!this.folio || this.folio === '—') return;
    this.resolucionService.getResoluciones(this.folio).subscribe({
      next: (resoluciones) => {
        const firmada = resoluciones.find((r) => r.estado === 'Firmada' && r.tieneDocumento) ?? resoluciones[0];
        if (firmada && firmada.tieneDocumento) {
          this.resolucionService.descargarResolucion(this.folio, firmada.id).subscribe({
            next: (blob) => {
              const url = URL.createObjectURL(blob);
              window.open(url, '_blank');
              setTimeout(() => URL.revokeObjectURL(url), 10000);
            },
          });
        }
      },
    });
  }
}
